import java.util.Scanner;

public class Main {
    static class Funksiya {
        long k, b;

        Funksiya(long k, long b) {
            this.k = k;
            this.b = b;
        }

        long qiymat(long x) {
            return k * x;
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        Funksiya f = new Funksiya(in.nextLong(), in.nextLong());
