class Funksiya {
public:
    long long k, b;

    Funksiya(long long k, long long b) : k(k), b(b) {}

    long long qiymat(long long x) const {
        return k * x;
    }
};

int main() {
    long long k, b;
    cin >> k >> b;
    Funksiya f(k, b);
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        long long x;
        cin >> x;
        cout << f.qiymat(x) << endl;
    }
    return 0;
}

